// v2.0: Config wird jetzt live aus HA gelesen.
// Dieser Node dient nur noch als Fallback falls HA States nicht verfügbar.
let config = global.get('smart_charging_config') || {};

config = {
    enabled: true,
    min_charge_current: config.min_charge_current || 7,
    max_charge_current: config.max_charge_current || 32,
    phases: config.phases || 3,
    min_battery_soc: config.min_battery_soc || 95,
    car_target_soc: config.car_target_soc || 80,
    last_update: new Date().toISOString()
};

global.set('smart_charging_config', config);
msg.payload = config;
return msg;

if (msg.data && msg.data.entity_id) {
    msg.payload = {
        entity: msg.data.entity_id,
        value: msg.payload,
        unit: msg.data.new_state ? msg.data.new_state.attributes.unit_of_measurement : ''
    };
}
return msg;

// v2.3: Lese alle Sensordaten direkt aus Home Assistant Global Context
const ha = global.get('homeassistant');
if (!ha || !ha.homeAssistant || !ha.homeAssistant.states) {
    node.warn('[v2.3] Home Assistant States nicht verfügbar!');
    return null;
}
const haStates = ha.homeAssistant.states;

// Prüfe ob alle wichtigen Entities vorhanden sind
const required = [
    'sensor.rct_power_storage_grid_power',
    'sensor.rct_power_storage_battery_state_of_charge',
    'sensor.rct_power_storage_battery_power',
    'sensor.easee_home_power',
    'sensor.easee_home_status',
    'sensor.zoe_battery',
    'sensor.zoe_plug_state'
];

const missing = required.filter(e => !haStates[e] || haStates[e].state === 'unavailable');
if (missing.length > 0) {
    node.warn('[v2.3] Fehlende Entities: ' + missing.join(', '));
    return null;
}

// Erstelle strukturiertes Datenobjekt
msg.payload = {
    rct: {
        grid_power: parseFloat(haStates['sensor.rct_power_storage_grid_power'].state) || 0,
        battery_soc: parseFloat(haStates['sensor.rct_power_storage_battery_state_of_charge'].state) || 0,
        battery_power: parseFloat(haStates['sensor.rct_power_storage_battery_power'].state) || 0,
        inverter_power: parseFloat((haStates['sensor.rct_power_storage_inverter_ac_power'] || {}).state) || 0,
        consumer_power: parseFloat((haStates['sensor.rct_power_storage_consumer_power'] || {}).state) || 0
    },
    easee: {
        power: parseFloat(haStates['sensor.easee_home_power'].state) || 0,
        current: parseFloat((haStates['sensor.easee_home_maximum_allowed_charge_current'] || {}).state) || 0,
        charging: haStates['sensor.easee_home_status'].state === 'charging'
    },
    zoe: {
        battery: parseFloat(haStates['sensor.zoe_battery'].state) || 0,
        plug_state: haStates['sensor.zoe_plug_state'].state,
        charge_state: (haStates['sensor.zoe_charge_state'] || {}).state || 'unknown'
    },
    timestamp: Date.now()
};

return msg;

const data = msg.payload;

// === v2.3: Lese alle Config-Werte LIVE aus Home Assistant ===
const ha = global.get('homeassistant');
if (!ha || !ha.homeAssistant || !ha.homeAssistant.states) {
    node.warn('[v2.3] Home Assistant States nicht verfügbar!');
    return null;
}
const haStates = ha.homeAssistant.states;

const ladeModus = (haStates['input_select.lade_modus'] || {}).state || 'stoppen';
const socOverride = (haStates['input_boolean.soc_override'] || {}).state === 'on';
const maxChargeCurrent = parseFloat((haStates['input_number.max_charge_current'] || {}).state) || 32;
const minChargeCurrent = parseFloat((haStates['input_number.min_charge_current'] || {}).state) || 7;
const carTargetSoc = parseFloat((haStates['input_number.car_target_soc'] || {}).state) || 80;
const batteryPriority = (haStates['input_boolean.battery_priority'] || {}).state === 'on';
const minBatterySoc = parseFloat((haStates['input_number.min_battery_soc'] || {}).state) || 95;
const phases = parseFloat((haStates['input_number.phases'] || {}).state) || 3;
const preventBatteryDischarge = (haStates['input_boolean.prevent_battery_discharge'] || {}).state === 'on';
const tibberEnabled = (haStates['input_boolean.tibber_enabled'] || {}).state === 'on';
const bridgeMaxMinutes = parseFloat((haStates['input_number.bridge_max_minutes'] || {}).state) || 10;

// === v2.3: Günstigster-Strom-Erkennung - Tagestief + 15% Toleranz ===
// Läuft IMMER (unabhängig von tibber_enabled), damit der eigenständige
// Modus "günstigster_strom" jederzeit funktioniert. tibber_enabled steuert
// nur noch, ob Automatik bei PV-Mangel zusätzlich auf Günstigstrom zurückfällt.
const priceEntity = haStates['sensor.sectorchan_electricity_price'] || {};
const currentPrice = parseFloat(priceEntity.state) || 0;
const minPrice = parseFloat((priceEntity.attributes || {}).min_price) || 0;
const priceThreshold = minPrice * 1.15;
const isCheapestNow = currentPrice > 0 && currentPrice <= priceThreshold;

// Config für nachfolgende Nodes mitgeben
msg.payload.config = {
    lade_modus: ladeModus,
    soc_override: socOverride,
    max_charge_current: maxChargeCurrent,
    min_charge_current: minChargeCurrent,
    car_target_soc: carTargetSoc,
    battery_priority: batteryPriority,
    min_battery_soc: minBatterySoc,
    phases: phases,
    prevent_battery_discharge: preventBatteryDischarge,
    tibber_enabled: tibberEnabled,
    tibber_current_price: currentPrice,
    tibber_min_price: minPrice,
    tibber_threshold: priceThreshold,
    is_cheapest_now: isCheapestNow,
    bridge_max_minutes: bridgeMaxMinutes
};

// === MODUS: STOPPEN ===
if (ladeModus === 'stoppen') {
    msg.payload.control = { action: 'stop', reason: 'Modus: Stoppen', mode: 'stoppen' };
    return msg;
}

// === Prüfe ob Auto angeschlossen ===
const carPluggedIn = data.zoe.plug_state === 'Plugged in' || data.zoe.plug_state === 'plugged';
if (!carPluggedIn) {
    msg.payload.control = { action: 'stop', reason: 'Fahrzeug nicht angeschlossen', mode: 'idle' };
    return msg;
}

// === v2.3: SOC-Prüfung EINHEITLICH für alle Modi - per soc_override überbrückbar ===
// Automatik verlor damit ihr bisheriges Hard-Limit und verhält sich wie
// laden/überschuss/günstigster_strom: 80%-Ziel, aber mit dem Schalter übersteuerbar.
if (!socOverride && data.zoe.battery >= carTargetSoc) {
    msg.payload.control = { action: 'stop', reason: 'Auto-SOC ' + data.zoe.battery + '% >= ' + carTargetSoc + '% (SOC-Override: AUS)', mode: ladeModus };
    return msg;
}

// === MODUS: MANUELL (laden) ===
// Direkt mit max_charge_current laden, keine PV-Berechnung nötig
if (ladeModus === 'laden') {
    msg.payload.control = {
        action: 'force_charge',
        reason: 'Manuell laden mit ' + maxChargeCurrent + 'A',
        target_current: maxChargeCurrent,
        mode: 'laden'
    };
    return msg;
}

// === MODI: automatik, überschuss, günstigster_strom → weiter zur Entscheidungslogik ===

// Batterie-Priorität prüfen (gilt nicht für "laden", das oben bereits behandelt wurde)
if (batteryPriority && data.rct.battery_soc < minBatterySoc) {
    msg.payload.control = { action: 'stop', reason: 'Batterie-Priorität: SOC ' + data.rct.battery_soc + '% < ' + minBatterySoc + '%', mode: ladeModus };
    return msg;
}

// Berechne verfügbaren PV-Überschuss
// (für günstigster_strom mitgeliefert, aber dort für die Ladeentscheidung ungenutzt)
let available_surplus = 0;

if (data.rct.grid_power < 0) {
    // Es wird eingespeist
    available_surplus = Math.abs(data.rct.grid_power);
    // Addiere aktuelle Wallbox-Leistung falls schon am Laden
    if (data.easee.charging && data.easee.power > 0) {
        available_surplus += data.easee.power;
    }
} else {
    // Es wird bezogen
    if (data.easee.charging && data.easee.power > 0) {
        available_surplus = data.easee.power - data.rct.grid_power;
    } else {
        available_surplus = -data.rct.grid_power;
    }
}

// Batterie-Entladungsschutz
if (preventBatteryDischarge && data.rct.battery_power > 0) {
    available_surplus -= data.rct.battery_power;
}

msg.payload.calculated = {
    available_surplus: Math.round(available_surplus),
    grid_power: data.rct.grid_power,
    battery_power: data.rct.battery_power,
    battery_soc: data.rct.battery_soc,
    current_charging_power: data.easee.power
};

return msg;

const data = msg.payload;
const config = data.config;

// === MANUELLES LADEN: Direkt durchreichen ===
if (data.control && data.control.action === 'force_charge') {
    const phases = config.phases;
    msg.payload.control.calculated_power = Math.round(data.control.target_current * 230 * phases);
    flow.set('bridge_active', false);
    flow.set('bridge_start_ts', null);
    return [null, msg, null, null]; // Output 2: Start + Set Current
}

// === STOP bereits gesetzt (SOC-Limit, nicht angeschlossen, Batterie-Priorität, etc.) ===
if (data.control && data.control.action === 'stop') {
    flow.set('bridge_active', false);
    flow.set('bridge_start_ts', null);
    return [msg, null, null, null]; // Output 1: Stop
}

// === PV-/PREIS-LOGIK (für Modi: automatik, überschuss, günstigster_strom) ===
const surplus = data.calculated.available_surplus;
const isCharging = data.easee.charging;
const phases = config.phases;
const minCurrent = config.min_charge_current;
const maxCurrent = config.max_charge_current;
const mode = config.lade_modus;
const isCheapestNow = config.is_cheapest_now;
const bridgeMaxMinutes = config.bridge_max_minutes;

function calculateCurrent(power_watts) {
    if (phases === 3) {
        return power_watts / (230 * phases);
    }
    return power_watts / 230;
}

function calculatePower(current_ampere) {
    if (phases === 3) {
        return current_ampere * 230 * phases;
    }
    return current_ampere * 230;
}

function clearBridge() {
    flow.set('bridge_active', false);
    flow.set('bridge_start_ts', null);
}

let targetCurrent = Math.round(calculateCurrent(surplus));
targetCurrent = Math.max(minCurrent, Math.min(maxCurrent, targetCurrent));

let action = 'hold';
let reason = '';
let tibberBoost = false;

if (mode === 'günstigster_strom') {
    // === MODUS: GÜNSTIGSTER STROM - rein preisgetrieben, PV-Überschuss irrelevant ===
    clearBridge();
    const priceCt = (config.tibber_current_price * 100).toFixed(1);
    const thresholdCt = (config.tibber_threshold * 100).toFixed(1);
    if (isCheapestNow) {
        targetCurrent = maxCurrent;
        if (isCharging) {
            action = 'charge';
            reason = 'GÜNSTIGSTER STROM: ' + priceCt + ' ct <= Tagestief+15% (' + thresholdCt + ' ct) -> ' + targetCurrent + 'A';
        } else {
            action = 'start';
            reason = 'GÜNSTIGSTER STROM Start: ' + priceCt + ' ct <= ' + thresholdCt + ' ct -> ' + targetCurrent + 'A';
        }
    } else {
        if (isCharging) {
            action = 'stop';
            reason = 'GÜNSTIGSTER STROM: Preis ' + priceCt + ' ct > Schwelle ' + thresholdCt + ' ct - nicht mehr die günstigste Phase';
        } else {
            action = 'hold';
            reason = 'GÜNSTIGSTER STROM: Warte auf Tagestief (' + priceCt + ' ct > ' + thresholdCt + ' ct)';
        }
    }
} else {
    // === MODI: AUTOMATIK + ÜBERSCHUSS ===
    // automatik: PV zuerst, bei PV-Mangel optional Preis-Fallback (tibber_enabled)
    // überschuss: ausschließlich PV, kein Preis-Fallback
    const minStartPower = 3600;

    if (surplus >= minStartPower) {
        clearBridge();
        if (isCharging) {
            action = 'charge';
            reason = mode + ': ' + Math.round(surplus) + 'W -> ' + targetCurrent + 'A';
        } else {
            action = 'start';
            reason = mode + ' Start: ' + Math.round(surplus) + 'W -> ' + targetCurrent + 'A';
        }
    } else if (mode === 'automatik' && config.tibber_enabled && isCheapestNow) {
        // PV reicht nicht -> Fallback auf günstigsten Strompreis (nur im Automatik-Modus)
        clearBridge();
        targetCurrent = maxCurrent;
        tibberBoost = true;
        const priceCt = (config.tibber_current_price * 100).toFixed(1);
        if (isCharging) {
            action = 'charge';
            reason = 'AUTOMATIK-FALLBACK Günstigstrom: PV ' + Math.round(surplus) + 'W unzureichend, Preis ' + priceCt + ' ct günstig -> ' + targetCurrent + 'A';
        } else {
            action = 'start';
            reason = 'AUTOMATIK-FALLBACK Günstigstrom Start: Preis ' + priceCt + ' ct günstig -> ' + targetCurrent + 'A';
        }
    } else if (isCharging) {
        // Zu wenig Überschuss und kein Preis-Fallback -> Wolken-Überbrückung versuchen
        // (verhindert Start/Stopp-Geflacker bei kurzen Einbrüchen, z.B. Wolken)
        const bridgeNow = Date.now();
        let bridgeStart = flow.get('bridge_start_ts');
        if (!bridgeStart) {
            bridgeStart = bridgeNow;
            flow.set('bridge_active', true);
            flow.set('bridge_start_ts', bridgeNow);
        }
        const elapsedMin = (bridgeNow - bridgeStart) / 60000;
        if (elapsedMin < bridgeMaxMinutes) {
            action = 'charge';
            targetCurrent = minCurrent;
            reason = mode + ': ÜBERBRÜCKUNG (' + elapsedMin.toFixed(1) + '/' + bridgeMaxMinutes + ' min) bei ' + Math.round(surplus) + 'W -> ' + targetCurrent + 'A';
        } else {
            action = 'stop';
            reason = mode + ': Überbrückung abgelaufen (' + bridgeMaxMinutes + ' min) - Überschuss weiter zu gering (' + Math.round(surplus) + 'W)';
            clearBridge();
        }
    } else {
        action = 'hold';
        reason = mode + ': Warte auf Überschuss (' + Math.round(surplus) + 'W < ' + Math.round(minStartPower) + 'W)';
        clearBridge();
    }
}

// === API-Throttling (aus v1.7 beibehalten) ===
const now = Date.now();
const lastSetCurrent = flow.get('last_api_current') || 0;
const lastApiCall = flow.get('last_api_timestamp') || 0;
const timeSinceLastCall = (now - lastApiCall) / 1000;

// Kein API-Call wenn Strom unverändert
if (action === 'charge' && targetCurrent === lastSetCurrent) {
    action = 'hold';
}
// Min. 30s zwischen API-Calls
if (action === 'charge' && timeSinceLastCall < 30 && targetCurrent !== lastSetCurrent) {
    action = 'hold';
}
// Nur signifikante Änderungen (>=1A)
if (action === 'charge' && Math.abs(targetCurrent - lastSetCurrent) < 1) {
    targetCurrent = lastSetCurrent;
    action = 'hold';
}

// Tracking für nächsten Call
if (action === 'charge' || action === 'start') {
    flow.set('last_api_current', targetCurrent);
    flow.set('last_api_timestamp', now);
}

// Control-Message
msg.payload.control = {
    action: action,
    target_current: targetCurrent,
    mode: mode,
    reason: reason,
    calculated_power: Math.round(calculatePower(targetCurrent)),
    tibber_boost: tibberBoost
};

// Debug-Logging
if (action !== 'hold') {
    node.warn('═══ PV-Laden v2.3 ═══');
    node.warn('[MODE] ' + mode);
    if (tibberBoost) {
        node.warn('[FALLBACK] Automatik-Günstigstrom-Boost aktiv: ' + (config.tibber_current_price * 100).toFixed(1) + ' ct/kWh (Schwelle: ' + (config.tibber_threshold * 100).toFixed(1) + ' ct)');
    }
    node.warn('[PV] Überschuss: ' + Math.round(surplus) + 'W');
    node.warn('[TGT] ' + targetCurrent + 'A (' + Math.round(calculatePower(targetCurrent)) + 'W)');
    node.warn('[ACT] ' + action + ' | ' + reason);
    node.warn('═════════════════════');
}

// Routing
if (action === 'stop') {
    return [msg, null, null, null]; // Output 1: Stop
} else if (action === 'start') {
    return [null, msg, null, null]; // Output 2: Start
} else if (action === 'charge') {
    return [null, null, msg, null]; // Output 3: Adjust Current
} else {
    return [null, null, null, msg]; // Output 4: Hold/Idle
}

// v2.4 FIX: Ersetzt den alten RBE-Filter auf payload.control.reason.
// Bug: RBE blockierte JEDEN weiteren Pause-Call, sobald der reason-Text
// einmal durchgelassen wurde (z.B. konstant 'Modus: Stoppen'). Wurde die
// Wallbox danach unabhaengig vom Flow gestartet (z.B. Easee startet
// selbst beim Einstecken des Fahrzeugs), kam nie wieder ein Pause-Befehl,
// obwohl Modus 'stoppen' oder das 80%-SOC-Limit weiterhin aktiv war.
//
// Fix: Nur senden, wenn die Wallbox laut aktuellem State TATSAECHLICH
// laedt, und hoechstens 1x pro Minute (verhindert 403 Rate-Limit bei
// der Easee-API). Dadurch wird der Stop-Befehl so lange wiederholt,
// bis die Wallbox tatsaechlich pausiert - unabhaengig vom reason-Text.
const charging = msg.payload.easee && msg.payload.easee.charging;
if (!charging) {
    return null;
}
const now = Date.now();
const lastCall = flow.get('last_stop_api_timestamp') || 0;
if (now - lastCall < 60000) {
    return null;
}
flow.set('last_stop_api_timestamp', now);
return msg;

const control = msg.payload.control;
const data = msg.payload;

// Erstelle Log-Eintrag
const logEntry = {
    timestamp: new Date().toISOString(),
    action: control.action,
    mode: control.mode || 'unknown',
    reason: control.reason,
    target_current: control.target_current || 0,
    calculated_power: control.calculated_power || 0,
    available_surplus: data.calculated ? data.calculated.available_surplus : 0,
    battery_soc: data.rct ? data.rct.battery_soc : 0,
    car_soc: data.zoe ? data.zoe.battery : 0
};

// Speichere letzte 100 Log-Einträge
let logs = global.get('charging_logs') || [];
logs.unshift(logEntry);
if (logs.length > 100) logs = logs.slice(0, 100);
global.set('charging_logs', logs);

// Update Status für Dashboard
const status = {
    mode: control.mode || 'unknown',
    action: control.action,
    current_charging: data.easee ? data.easee.charging : false,
    target_current: control.target_current,
    available_surplus: data.calculated ? data.calculated.available_surplus : 0,
    battery_soc: data.rct ? data.rct.battery_soc : 0,
    car_soc: data.zoe ? data.zoe.battery : 0,
    last_update: new Date().toISOString(),
    reason: control.reason
};

global.set('charging_status', status);

msg.payload = logEntry;
return msg;

const control = msg.payload.control;
const config = msg.payload.config;
const preventDischarge = config.prevent_battery_discharge;

if (!preventDischarge) {
    // Schutz deaktiviert: immer unlocken falls noch gelockt
    if (flow.get('battery_locked')) {
        flow.set('battery_locked', false);
        node.warn('[v2.1] RCT Batterie UNLOCK (Schutz deaktiviert)');
        return [null, msg];
    }
    return null;
}

const isStarting = control.action === 'start' || control.action === 'charge' || control.action === 'force_charge';
const isStopping = control.action === 'stop' || control.action === 'hold';

const currentLockState = flow.get('battery_locked') || false;

// Lock nur wenn Wallbox tatsächlich startet/lädt
if (isStarting && !currentLockState) {
    flow.set('battery_locked', true);
    node.warn('[v2.1] RCT Batterie LOCK aktiviert (Wallbox lädt)');
    return [msg, null];
}

// Unlock bei JEDEM Stop — auch wenn interner State inkonsistent ist
if (isStopping && currentLockState) {
    flow.set('battery_locked', false);
    node.warn('[v2.1] RCT Batterie UNLOCK (Wallbox gestoppt)');
    return [null, msg];
}

return null;
